def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return (seen[target - n], i)
        seen[n] = i

def is_palindrome(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        out.append('FizzBuzz' if i % 15 == 0 else 'Fizz' if i % 3 == 0 else 'Buzz' if i % 5 == 0 else str(i))
    return out

from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.d = OrderedDict()
    def get(self, key):
        if key not in self.d:
            return -1
        self.d.move_to_end(key)
        return self.d[key]
    def put(self, key, value):
        if key in self.d:
            self.d.move_to_end(key)
        self.d[key] = value
        if len(self.d) > self.cap:
            self.d.popitem(last=False)

def merge(intervals):
    if not intervals:
        return []
    iv = sorted(intervals)
    out = [list(iv[0])]
    for s, e in iv[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return [tuple(x) for x in out]

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def is_valid(s):
    m = {')':'(', ']':'[', '}':'{'}
    st = []
    for c in s:
        if c in m:
            if not st or st.pop() != m[c]:
                return False
        else:
            st.append(c)
    return not st

def max_subarray(nums):
    best = cur = nums[0]
    for n in nums[1:]:
        cur = max(n, cur + n)
        best = max(best, cur)
    return best

def climb_stairs(n):
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def group_anagrams(strs):
    from collections import defaultdict
    d = defaultdict(list)
    for w in strs:
        d[''.join(sorted(w))].append(w)
    return list(d.values())

def flatten(d, parent=''):
    out = {}
    for k, v in d.items():
        key = f'{parent}.{k}' if parent else k
        if isinstance(v, dict):
            out.update(flatten(v, key))
        else:
            out[key] = v
    return out

from collections import deque
class RateLimiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.q = deque()
    def allow(self, ts):
        while self.q and self.q[0] <= ts - self.window:
            self.q.popleft()
        if len(self.q) < self.limit:
            self.q.append(ts)
            return True
        return False

def top_k(nums, k):
    from collections import Counter
    return [x for x, _ in sorted(Counter(nums).items(), key=lambda kv: (-kv[1], kv[0]))[:k]]

def parse_log(line):
    date, time, level, rest = line.split(' ', 3)
    source, message = rest.split(': ', 1)
    return {'date': date, 'time': time, 'level': level, 'source': source, 'message': message}

def lis(nums):
    import bisect
    tails = []
    for n in nums:
        i = bisect.bisect_left(tails, n)
        if i == len(tails):
            tails.append(n)
        else:
            tails[i] = n
    return len(tails)

def retry(times):
    def deco(fn):
        def wrapper(*a, **kw):
            last = None
            for _ in range(times):
                try:
                    return fn(*a, **kw)
                except Exception as e:
                    last = e
            raise last
        return wrapper
    return deco

