def ttl_get(store, key, now):
    if key not in store:
        return None
    v, exp = store[key]
    if exp <= now:
        del store[key]
        return None
    return v

def can_reach(begin, end, words):
    from collections import deque
    words = set(words) | {begin}
    if end not in words:
        return False
    q, seen = deque([begin]), {begin}
    while q:
        w = q.popleft()
        if w == end:
            return True
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                n = w[:i] + c + w[i+1:]
                if n in words and n not in seen:
                    seen.add(n)
                    q.append(n)
    return False

def safe_divide(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError('numeric only')
    if b == 0:
        return 'undefined'
    return round(a / b, 4)
